// BreakPoint brand logos, compiled into the bundle as base64 strings.
// Reading from /public at runtime fails on Vercel because serverless
// functions don't ship the /public folder in their bundle, so the
// signature renderer + resume brander import these constants instead
// of hitting the filesystem.
//
// DEFAULT_BRAND_LOGO_BASE64 — the white-background logo used in the
//   email signature (matches what looks right against the recipient's
//   email body).
// BRAND_LOGO_TRANSPARENT_BASE64 — the transparent-background variant
//   (just the three circles + "BreakPoint TALENT" wordmark). Used by
//   the Brand mode of the Edit Resume modal so the logo overlays
//   cleanly on top of resume content without a white box around it.
//
// Regenerate from the canonical source files via:
//   node -e 'process.stdout.write(require("fs").readFileSync("public/brand/breakpoint_logo_signature.png").toString("base64"))' > /tmp/sig.b64
//   node -e 'process.stdout.write(require("fs").readFileSync("public/brand/breakpoint_logo_transparent.png").toString("base64"))' > /tmp/transp.b64
// then paste contents into the matching exports below.

export const DEFAULT_BRAND_LOGO_MIME = "image/png";
export const BRAND_LOGO_TRANSPARENT_MIME = "image/png";

export const DEFAULT_BRAND_LOGO_BASE64 =
  "";

export const BRAND_LOGO_TRANSPARENT_BASE64 =
  "";
